def kthLargestStream(k, nums, adds):
    import heapq
    heap = []
    for x in nums:
        heapq.heappush(heap, x)
        if len(heap) > k: heapq.heappop(heap)
    res = []
    for x in adds:
        heapq.heappush(heap, x)
        if len(heap) > k: heapq.heappop(heap)
        res.append(heap[0])
    return res

