#include <vector>
#include <queue>
using namespace std;
class Solution {
public:
    vector<int> kthLargestStream(int k, vector<int>& nums, vector<int>& adds) {
        priority_queue<int, vector<int>, greater<int>> pq;
        for (int x : nums) { pq.push(x); if (pq.size() > k) pq.pop(); }
        vector<int> res;
        for (int x : adds) {
            pq.push(x);
            if (pq.size() > k) pq.pop();
            res.push_back(pq.top());
        }
        return res;
    }
};
